def flag_large_backorder_totals(rows: list[dict[str, object]], threshold: float = 5000) -> list[dict[str, object]]:
    """Flag backorder rows whose total crosses the review threshold."""
    flagged: list[dict[str, object]] = []
    for row in rows:
